tool_schemas.implementation:
def update_page(site_id, wp_page_id, elementor_data_json, title=None, slug=None, wp_status=None, elementor_edit_mode=None, elementor_template_type=None, raw_meta=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0057000" if __import__("os").path.isdir("./environment_mix/0057000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _truncate_obj(o, max_chars=2000):
        try:
            s = json.dumps(o, ensure_ascii=False)
            if len(s) <= max_chars:
                return o
            return {"_truncated": True, "length": len(s), "preview": s[:max_chars]}
        except Exception:
            return {"_truncated": True, "note": "non-serializable"}

    def _op_row_base(tool, site_id_val):
        return {
            "id": _new_id("elm_op"),
            "site_id": site_id_val,
            "tool_name": tool,
            "page_id": None,
            "wp_page_id": None,
            "slug": None,
            "input_file_id": None,
            "output_file_id": None,
            "request_payload": None,
            "response_payload": None,
            "http_status": None,
            "success": None,
            "status": "queued",
            "error_message": None,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }

    def _transition_op(op, new_status):
        allowed = {"queued": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        cur = op.get("status")
        if new_status not in allowed.get(cur, []):
            return False
        op["status"] = new_status
        op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        return True

    def _auth_pick_key_for_site(sid):
        keys = _load("api_keys.json")
        sites = _load("wp_sites.json")
        site = next((s for s in sites if s.get("id") == sid), None)
        if not site:
            return None, None
        for k in keys:
            if k.get("status") != "active":
                continue
            allow = k.get("allowed_site_ids")
            if allow is not None and sid not in allow:
                continue
            return k, site
        return None, site

    def _parse_iso_z(ts):
        if not ts or not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _quota_check(key_row):
        ops = _load("page_operations.json")
        now_dt = datetime.datetime.utcnow()
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        key_id = key_row.get("id")
        rl = key_row.get("rate_limit_per_minute")
        dq = key_row.get("daily_quota_ops")

        def _belongs(op):
            return op.get("request_payload", {}).get("_api_key_id") == key_id

        last_min = 0
        last_day = 0
        for op in ops:
            if not _belongs(op):
                continue
            ts = _parse_iso_z(op.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                last_min += 1
            if ts >= day_ago:
                last_day += 1

        if isinstance(rl, int) and rl > 0 and last_min + 1 > rl:
            return "RATE_LIMIT", f"Rate limit exceeded: {rl}/minute"
        if isinstance(dq, int) and dq > 0 and last_day + 1 > dq:
            return "QUOTA_EXCEEDED", f"Daily quota exceeded: {dq}/day"
        return None, None

    # Validate
    if not isinstance(site_id, str) or not re.match(r"^elm_site_[0-9A-HJKMNP-TV-Z]{17,}$", site_id):
        ops = _load("page_operations.json")
        op = _op_row_base("update_page", site_id if isinstance(site_id, str) else "unknown")
        op["request_payload"] = {"site_id": site_id, "wp_page_id": wp_page_id}
        _transition_op(op, "failed"); op["error_message"] = "Invalid site_id"
        op["duration_ms"] = int((time.time() - t0) * 1000)
        ops.append(op); _save("page_operations.json", ops)
        return _err("VALIDATION_ERROR", "Invalid site_id")
    if not isinstance(wp_page_id, int) or wp_page_id < 1:
        ops = _load("page_operations.json")
        op = _op_row_base("update_page", site_id)
        op["request_payload"] = {"site_id": site_id, "wp_page_id": wp_page_id}
        _transition_op(op, "failed"); op["error_message"] = "Invalid wp_page_id"
        op["duration_ms"] = int((time.time() - t0) * 1000)
        ops.append(op); _save("page_operations.json", ops)
        return _err("VALIDATION_ERROR", "wp_page_id must be an integer >= 1")
    if not isinstance(elementor_data_json, (dict, list)):
        ops = _load("page_operations.json")
        op = _op_row_base("update_page", site_id)
        op["request_payload"] = {"site_id": site_id, "wp_page_id": wp_page_id}
        _transition_op(op, "failed"); op["error_message"] = "Invalid elementor_data_json"
        op["duration_ms"] = int((time.time() - t0) * 1000)
        ops.append(op); _save("page_operations.json", ops)
        return _err("VALIDATION_ERROR", "elementor_data_json is required and must be an object/array")
    if title is not None and (not isinstance(title, str) or not title.strip()):
        ops = _load("page_operations.json")
        op = _op_row_base("update_page", site_id)
        op["request_payload"] = {"site_id": site_id, "wp_page_id": wp_page_id, "title": title}
        _transition_op(op, "failed"); op["error_message"] = "Invalid title"
        op["duration_ms"] = int((time.time() - t0) * 1000)
        ops.append(op); _save("page_operations.json", ops)
        return _err("VALIDATION_ERROR", "title must be a non-empty string when provided")
    if slug is not None:
        if not isinstance(slug, str) or not (1 <= len(slug) <= 200):
            ops = _load("page_operations.json")
            op = _op_row_base("update_page", site_id)
            op["request_payload"] = {"site_id": site_id, "wp_page_id": wp_page_id, "slug": slug}
            _transition_op(op, "failed"); op["error_message"] = "Invalid slug"
            op["duration_ms"] = int((time.time() - t0) * 1000)
            ops.append(op); _save("page_operations.json", ops)
            return _err("VALIDATION_ERROR", "slug must be a string length 1..200")
    allowed_wp_status = {"publish", "draft", "pending", "private", "future", "trash", "inherit", "unknown"}
    if wp_status is not None and (not isinstance(wp_status, str) or wp_status not in allowed_wp_status):
        ops = _load("page_operations.json")
        op = _op_row_base("update_page", site_id)
        op["request_payload"] = {"site_id": site_id, "wp_page_id": wp_page_id, "wp_status": wp_status}
        _transition_op(op, "failed"); op["error_message"] = "Invalid wp_status"
        op["duration_ms"] = int((time.time() - t0) * 1000)
        ops.append(op); _save("page_operations.json", ops)
        return _err("VALIDATION_ERROR", "Invalid wp_status")
    allowed_edit_mode = {"builder", "default", "unknown"}
    if elementor_edit_mode is not None and (not isinstance(elementor_edit_mode, str) or elementor_edit_mode not in allowed_edit_mode):
        ops = _load("page_operations.json")
        op = _op_row_base("update_page", site_id)
        op["request_payload"] = {"site_id": site_id, "wp_page_id": wp_page_id, "elementor_edit_mode": elementor_edit_mode}
        _transition_op(op, "failed"); op["error_message"] = "Invalid elementor_edit_mode"
        op["duration_ms"] = int((time.time() - t0) * 1000)
        ops.append(op); _save("page_operations.json", ops)
        return _err("VALIDATION_ERROR", "Invalid elementor_edit_mode")
    if elementor_template_type is not None and not isinstance(elementor_template_type, str):
        ops = _load("page_operations.json")
        op = _op_row_base("update_page", site_id)
        op["request_payload"] = {"site_id": site_id, "wp_page_id": wp_page_id, "elementor_template_type": elementor_template_type}
        _transition_op(op, "failed"); op["error_message"] = "Invalid elementor_template_type"
        op["duration_ms"] = int((time.time() - t0) * 1000)
        ops.append(op); _save("page_operations.json", ops)
        return _err("VALIDATION_ERROR", "elementor_template_type must be a string when provided")
    if raw_meta is not None and not isinstance(raw_meta, dict):
        ops = _load("page_operations.json")
        op = _op_row_base("update_page", site_id)
        op["request_payload"] = {"site_id": site_id, "wp_page_id": wp_page_id}
        _transition_op(op, "failed"); op["error_message"] = "Invalid raw_meta"
        op["duration_ms"] = int((time.time() - t0) * 1000)
        ops.append(op); _save("page_operations.json", ops)
        return _err("VALIDATION_ERROR", "raw_meta must be an object when provided")

    key_row, site_row = _auth_pick_key_for_site(site_id)

    # Create op
    ops = _load("page_operations.json")
    op = _op_row_base("update_page", site_id)
    op["wp_page_id"] = wp_page_id
    op["slug"] = slug
    op["request_payload"] = {
        "_api_key_id": key_row.get("id") if key_row else None,
        "site_id": site_id,
        "wp_page_id": wp_page_id,
        "title": title,
        "slug": slug,
        "wp_status": wp_status,
        "elementor_edit_mode": elementor_edit_mode,
        "elementor_template_type": elementor_template_type,
        "raw_meta": _truncate_obj(raw_meta) if raw_meta is not None else None,
        "elementor_data_json": _truncate_obj(elementor_data_json),
    }
    ops.append(op); _save("page_operations.json", ops)

    if not site_row:
        ops = _load("page_operations.json")
        op2 = next(o for o in ops if o["id"] == op["id"])
        _transition_op(op2, "failed"); op2["error_message"] = "Site not found"
        op2["duration_ms"] = int((time.time() - t0) * 1000)
        _save("page_operations.json", ops)
        return _err("NOT_FOUND", "site_id not found")
    if site_row.get("status") != "active":
        ops = _load("page_operations.json")
        op2 = next(o for o in ops if o["id"] == op["id"])
        _transition_op(op2, "failed"); op2["error_message"] = "Site disabled"
        op2["duration_ms"] = int((time.time() - t0) * 1000)
        _save("page_operations.json", ops)
        return _err("UNAUTHORIZED", "Site is disabled")
    if not key_row:
        ops = _load("page_operations.json")
        op2 = next(o for o in ops if o["id"] == op["id"])
        _transition_op(op2, "failed"); op2["error_message"] = "No API key authorized for site"
        op2["duration_ms"] = int((time.time() - t0) * 1000)
        _save("page_operations.json", ops)
        return _err("UNAUTHORIZED", "No authorized API key available")

    qcode, qmsg = _quota_check(key_row)
    if qcode:
        ops = _load("page_operations.json")
        op2 = next(o for o in ops if o["id"] == op["id"])
        _transition_op(op2, "failed"); op2["error_message"] = qmsg
        op2["duration_ms"] = int((time.time() - t0) * 1000)
        _save("page_operations.json", ops)
        return _err(qcode, qmsg)

    # update key usage
    keys = _load("api_keys.json")
    for k in keys:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", keys)

    # Running
    ops = _load("page_operations.json")
    op2 = next(o for o in ops if o["id"] == op["id"])
    if not _transition_op(op2, "running"):
        op2["error_message"] = "Invalid operation status transition"
        _save("page_operations.json", ops)
        return _err("INVALID_TRANSITION", "Operation status transition invalid")
    _save("page_operations.json", ops)

    # Locate page
    pages = _load("wp_pages.json")
    page = next((p for p in pages if p.get("site_id") == site_id and p.get("wp_page_id") == wp_page_id and p.get("deleted_at") is None), None)
    if not page:
        ops = _load("page_operations.json")
        op3 = next(o for o in ops if o["id"] == op["id"])
        op3["http_status"] = 404
        _transition_op(op3, "failed")
        op3["success"] = False
        op3["error_message"] = "Page not found"
        op3["duration_ms"] = int((time.time() - t0) * 1000)
        _save("page_operations.json", ops)
        return _err("NOT_FOUND", "page not found")

    # Slug uniqueness check (where deleted_at is null)
    if slug is not None and slug != page.get("slug"):
        for p in pages:
            if p.get("site_id") == site_id and p.get("deleted_at") is None and p.get("slug") == slug and p.get("id") != page.get("id"):
                ops = _load("page_operations.json")
                op3 = next(o for o in ops if o["id"] == op["id"])
                op3["http_status"] = 409
                _transition_op(op3, "failed")
                op3["success"] = False
                op3["error_message"] = "Slug already exists"
                op3["duration_ms"] = int((time.time() - t0) * 1000)
                _save("page_operations.json", ops)
                return _err("CONFLICT", "slug already exists for this site")

    # Apply update
    if title is not None:
        page["title"] = title
    if slug is not None:
        page["slug"] = slug
    if wp_status is not None:
        page["wp_status"] = wp_status
    page["elementor_data_json"] = elementor_data_json
    if elementor_edit_mode is not None:
        page["elementor_edit_mode"] = elementor_edit_mode
    if elementor_template_type is not None:
        page["elementor_template_type"] = elementor_template_type
    if raw_meta is not None:
        page["raw_meta"] = raw_meta

    # Cache lifecycle: mark fresh (fresh stays, stale->fresh, unknown->fresh)
    page["cache_state"] = "fresh"
    page["last_synced_at"] = now
    page["updated_at"] = now

    _save("wp_pages.json", pages)

    # Finish op
    ops = _load("page_operations.json")
    op4 = next(o for o in ops if o["id"] == op["id"])
    op4["page_id"] = page.get("id")
    op4["slug"] = page.get("slug")
    op4["http_status"] = 200
    op4["success"] = True
    op4["response_payload"] = {"updated": True, "page_id": page.get("id")}
    _transition_op(op4, "succeeded")
    op4["duration_ms"] = int((time.time() - t0) * 1000)
    _save("page_operations.json", ops)

    return {"success": True, "operation_id": op4["id"]}

def update_page_from_file(site_id, wp_page_id, file_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0057000" if __import__("os").path.isdir("./environment_mix/0057000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_rows(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        return []

    def _wrap(rows, original):
        # preserve original file shape
        if isinstance(original, dict) and "rows" in original:
            original["rows"] = rows
            return original
        return rows

    def _gen_id(prefix):
        # deterministic enough for offline store: prefix + timestamp + random
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        tail = "".join(secrets.choice(alphabet) for _ in range(26))
        return f"{prefix}{tail}"

    def _truncate(obj, max_str=2000, max_list=50, max_depth=3):
        def _t(o, d):
            if d <= 0:
                return "[truncated]"
            if o is None or isinstance(o, (bool, int, float)):
                return o
            if isinstance(o, str):
                return o if len(o) <= max_str else o[:max_str] + "…"
            if isinstance(o, dict):
                out = {}
                for i, (k, v) in enumerate(o.items()):
                    if i >= max_list:
                        out["…"] = f"{len(o) - max_list} more keys"
                        break
                    out[str(k)] = _t(v, d - 1)
                return out
            if isinstance(o, list):
                out = []
                for i, it in enumerate(o):
                    if i >= max_list:
                        out.append(f"… {len(o) - max_list} more items")
                        break
                    out.append(_t(it, d - 1))
                return out
            return str(o)
        return _t(obj, max_depth)

    t0 = time.time()
    now = _now_iso()

    # ---- validate inputs (schema) ----
    if not isinstance(site_id, str) or not re.match(r"^elm_site_[0-9A-HJKMNP-TV-Z]{17,}$", site_id):
        return _err("VALIDATION_ERROR", "Invalid site_id format.", field="site_id")
    if not isinstance(wp_page_id, int) or wp_page_id < 1:
        return _err("VALIDATION_ERROR", "Invalid wp_page_id; must be an integer >= 1.", field="wp_page_id")
    if not isinstance(file_id, str) or not re.match(r"^elm_file_[0-9A-HJKMNP-TV-Z]{17,}$", file_id):
        return _err("VALIDATION_ERROR", "Invalid file_id format.", field="file_id")

    # ---- load datastore ----
    sites_raw = _load("wp_sites.json")
    pages_raw = _load("wp_pages.json")
    files_raw = _load("page_files.json")
    ops_raw = _load("page_operations.json")
    keys_raw = _load("api_keys.json")

    sites = _ensure_rows(sites_raw)
    pages = _ensure_rows(pages_raw)
    pfiles = _ensure_rows(files_raw)
    ops = _ensure_rows(ops_raw)
    api_keys = _ensure_rows(keys_raw)

    # ---- resolve site ----
    site = next((s for s in sites if isinstance(s, dict) and s.get("id") == site_id), None)
    if not site:
        # must still record operation
        op_id = _gen_id("elm_op_")
        op = {
            "id": op_id,
            "site_id": site_id,
            "tool_name": "update_page_from_file",
            "page_id": None,
            "wp_page_id": wp_page_id,
            "slug": None,
            "input_file_id": file_id,
            "output_file_id": None,
            "request_payload": _truncate({"site_id": site_id, "wp_page_id": wp_page_id, "file_id": file_id}),
            "response_payload": None,
            "http_status": None,
            "success": False,
            "status": "failed",
            "error_message": "Site not found.",
            "duration_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("NOT_FOUND", "Site not found.", site_id=site_id)

    # ---- ambient auth & quota enforcement via any usable active api key ----
    # choose a key that can access this site and is within quotas; otherwise fail with RATE_LIMIT/QUOTA_EXCEEDED
    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)

    def _ops_for_key(key_id):
        out = []
        for r in ops:
            if isinstance(r, dict) and r.get("request_payload", {}).get("api_key_id") == key_id:
                out.append(r)
        return out

    # Backward-compatible: if older ops don't store api_key_id, also count them under a "global" bucket per key
    # by using key_prefix match not possible; so only enforce quotas when we can bind a key.
    usable_key = None
    quota_fail = None  # ("RATE_LIMIT"/"QUOTA_EXCEEDED", message)
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        allowed = k.get("allowed_site_ids")
        if allowed is not None:
            if not isinstance(allowed, list) or site_id not in allowed:
                continue
        # count operations for this key over last minute/day (only those that recorded api_key_id)
        kid = k.get("id")
        if not isinstance(kid, str):
            continue
        recent = 0
        daily = 0
        for r in _ops_for_key(kid):
            ts = _parse_iso(r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent += 1
            if ts >= day_ago:
                daily += 1
        rlim = k.get("rate_limit_per_minute")
        dlim = k.get("daily_quota_ops")
        if isinstance(rlim, int) and recent + 1 > rlim:
            quota_fail = ("RATE_LIMIT", "Quota exceeded (rate_limit_per_minute)")
            continue
        if isinstance(dlim, int) and daily + 1 > dlim:
            quota_fail = ("QUOTA_EXCEEDED", "Quota exceeded (daily_quota_ops)")
            continue
        usable_key = k
        quota_fail = None
        break

    # create operation row early (required), status queued -> running -> succeeded/failed
    op_id = _gen_id("elm_op_")
    op = {
        "id": op_id,
        "site_id": site_id,
        "tool_name": "update_page_from_file",
        "page_id": None,
        "wp_page_id": wp_page_id,
        "slug": None,
        "input_file_id": file_id,
        "output_file_id": None,
        "request_payload": _truncate({"site_id": site_id, "wp_page_id": wp_page_id, "file_id": file_id, "api_key_id": (usable_key or {}).get("id")}),
        "response_payload": None,
        "http_status": None,
        "success": None,
        "status": "queued",
        "error_message": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op)

    def _set_op_status(new_status, success=None, http_status=None, error_message=None, response_payload=None):
        # enforce lifecycle transitions
        transitions = {
            "queued": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        cur = op.get("status")
        if new_status != cur:
            if new_status not in transitions.get(cur, set()):
                # cannot raise; mark failed if illegal internal transition
                op["status"] = "failed"
                op["success"] = False if success is None else bool(success)
                op["error_message"] = f"Internal invalid transition {cur}->{new_status}"
                op["updated_at"] = _now_iso()
                return
            op["status"] = new_status
        if success is not None:
            op["success"] = bool(success)
        if http_status is not None:
            op["http_status"] = http_status
        if error_message is not None:
            op["error_message"] = error_message
        if response_payload is not None:
            op["response_payload"] = _truncate(response_payload)
        op["updated_at"] = _now_iso()

    # if no usable key exists, decide between unauthorized vs quota exceeded
    if not usable_key:
        if quota_fail:
            code, msg = quota_fail
            _set_op_status("failed", success=False, error_message=msg, response_payload={"error": msg})
            op["duration_ms"] = int((time.time() - t0) * 1000)
            _save("page_operations.json", _wrap(ops, ops_raw))
            return _err(code, msg)
        _set_op_status("failed", success=False, error_message="No authorized API key available for this site.", response_payload={"error": "unauthorized"})
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("UNAUTHORIZED", "No authorized API key available for this site.", site_id=site_id)

    # update key last_used_at
    usable_key["last_used_at"] = now
    usable_key["updated_at"] = now

    _set_op_status("running")

    # ---- resolve file ----
    pf = next((f for f in pfiles if isinstance(f, dict) and f.get("id") == file_id), None)
    if not pf:
        _set_op_status("failed", success=False, error_message="File not found.")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("NOT_FOUND", "File not found.", file_id=file_id)

    # enforce FK integrity and cross-site rules correctly:
    # page_files must belong to the same site_id as the request; page_id linkage is optional but if present must match.
    if pf.get("site_id") != site_id:
        _set_op_status("failed", success=False, error_message="Cross-site linking is forbidden: page_files.site_id must match the requested site_id.")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err(
            "CONFLICT",
            "Cross-site linking is forbidden: page_files.site_id must match the requested site_id.",
            rule="FK integrity: cross-site linking is forbidden (site_id must match across linked rows).",
            file_id=file_id,
            file_site_id=pf.get("site_id"),
            site_id=site_id,
        )

    # if file references a page_id, it must exist and be same site, but it MUST NOT block the call
    # when the file is otherwise usable (wp_page_id is authoritative for this tool).
    file_page_id = pf.get("page_id")
    if file_page_id is not None:
        page_row = next((p for p in pages if isinstance(p, dict) and p.get("id") == file_page_id), None)
        if not page_row:
            _set_op_status("failed", success=False, error_message="Referenced page_id in file does not exist.")
            op["duration_ms"] = int((time.time() - t0) * 1000)
            _save("api_keys.json", _wrap(api_keys, keys_raw))
            _save("page_operations.json", _wrap(ops, ops_raw))
            return _err("NOT_FOUND", "Referenced page_id in file does not exist.", page_id=file_page_id, file_id=file_id)
        if page_row.get("site_id") != site_id:
            _set_op_status("failed", success=False, error_message="Cross-site linking is forbidden: page_files.page_id must reference a page in the same site.")
            op["duration_ms"] = int((time.time() - t0) * 1000)
            _save("api_keys.json", _wrap(api_keys, keys_raw))
            _save("page_operations.json", _wrap(ops, ops_raw))
            return _err(
                "CONFLICT",
                "Cross-site linking is forbidden: page_files.page_id must reference a page in the same site.",
                rule="FK integrity: cross-site linking is forbidden (site_id must match across linked rows).",
                page_site_id=page_row.get("site_id"),
                site_id=site_id,
                file_id=file_id,
                page_id=file_page_id,
            )

    # file must be ready
    if pf.get("status") != "ready":
        _set_op_status("failed", success=False, error_message="Input file status must be 'ready'.")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("INVALID_TRANSITION", "Input file status must be 'ready'.", file_status=pf.get("status"), required_status="ready")

    # ---- read and parse file content (local_fs only; other backends cannot be read offline) ----
    storage_backend = pf.get("storage_backend")
    storage_path = pf.get("storage_path")
    if storage_backend not in ("local_fs", "s3", "gcs"):
        _set_op_status("failed", success=False, error_message="Invalid storage_backend.")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("VALIDATION_ERROR", "Invalid storage_backend.", storage_backend=storage_backend)

    if not isinstance(storage_path, str) or not storage_path.strip():
        _set_op_status("failed", success=False, error_message="Invalid storage_path.")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("VALIDATION_ERROR", "Invalid storage_path.", field="storage_path")

    payload = None
    if storage_backend != "local_fs":
        # Offline implementation: cannot fetch bytes from s3/gcs; treat as not found/unsupported.
        _set_op_status("failed", success=False, error_message=f"Cannot read file from {storage_backend} in offline datastore.")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("NOT_FOUND", f"Cannot read file from {storage_backend} in offline datastore.", storage_backend=storage_backend, storage_path=storage_path)

    try:
        with open(storage_path, "rb") as f:
            raw = f.read()
    except FileNotFoundError:
        _set_op_status("failed", success=False, error_message="File bytes not found on local_fs.")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("NOT_FOUND", "File bytes not found on local_fs.", storage_path=storage_path)
    except OSError as e:
        _set_op_status("failed", success=False, error_message="Failed to read file bytes.")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("CONFLICT", "Failed to read file bytes.", detail=str(e), storage_path=storage_path)

    try:
        payload = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        _set_op_status("failed", success=False, error_message="Input file is not valid UTF-8 JSON.")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("VALIDATION_ERROR", "Input file is not valid UTF-8 JSON.", file_id=file_id)
    except json.JSONDecodeError as e:
        _set_op_status("failed", success=False, error_message="Input file JSON invalid; cannot extract wp_page_id/_elementor_data")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("VALIDATION_ERROR", "Input file JSON invalid; cannot extract wp_page_id/_elementor_data", detail=str(e), file_id=file_id)

    if not isinstance(payload, dict):
        _set_op_status("failed", success=False, error_message="Input file JSON must be an object.")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("VALIDATION_ERROR", "Input file JSON must be an object.", file_id=file_id)

    # ---- extract identifiers ----
    file_wp_page_id = payload.get("wp_page_id")
    if not isinstance(file_wp_page_id, int) or file_wp_page_id < 1:
        _set_op_status("failed", success=False, error_message="Input file missing valid wp_page_id.")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("VALIDATION_ERROR", "Input file missing valid wp_page_id.", file_id=file_id)

    if file_wp_page_id != wp_page_id:
        _set_op_status("failed", success=False, error_message="wp_page_id does not match the file payload.")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("CONFLICT", "wp_page_id does not match the file payload.", wp_page_id=wp_page_id, file_wp_page_id=file_wp_page_id, file_id=file_id)

    elementor_data = payload.get("_elementor_data", payload.get("elementor_data_json"))
    if elementor_data is None:
        # allow update even if missing, but mark validation error as per rule
        _set_op_status("failed", success=False, error_message="Input file missing _elementor_data.")
        op["duration_ms"] = int((time.time() - t0) * 1000)
        _save("api_keys.json", _wrap(api_keys, keys_raw))
        _save("page_operations.json", _wrap(ops, ops_raw))
        return _err("VALIDATION_ERROR", "Input file missing _elementor_data.", file_id=file_id)

    slug = payload.get("slug")
    if slug is not None and not isinstance(slug, str):
        return _err("VALIDATION_ERROR", "Invalid slug type in file payload.", file_id=file_id)

    # ---- apply update semantics (offline: simulate WP update by persisting local cache) ----
    # Upsert wp_pages row for (site_id, wp_page_id). Do NOT invent remote HTTP outcomes; record http_status null.
    page = next((p for p in pages if isinstance(p, dict) and p.get("site_id") == site_id and p.get("wp_page_id") == wp_page_id), None)
    if page is None:
        # create minimal page cache row to reflect update (id convention elm_page_)
        page = {
            "id": _gen_id("elm_page_"),
            "site_id": site_id,
            "wp_page_id": wp_page_id,
            "slug": slug if isinstance(slug, str) and 1 <= len(slug) <= 200 else f"wp-{wp_page_id}",
            "title": payload.get("title") if isinstance(payload.get("title"), str) else None,
            "wp_status": payload.get("wp_status") if payload.get("wp_status") in ("publish", "draft", "pending", "private", "future", "trash", "inherit", "unknown") else "unknown",
            "link": payload.get("link") if isinstance(payload.get("link"), str) else None,
            "elementor_data_json": elementor_data if isinstance(elementor_data, (dict, list)) else elementor_data,
            "elementor_edit_mode": payload.get("_elementor_edit_mode") if payload.get("_elementor_edit_mode") in ("builder", "default", "unknown") else None,
            "elementor_template_type": payload.get("_elementor_template_type") if isinstance(payload.get("_elementor_template_type"), str) else None,
            "raw_meta": payload.get("raw_meta") if isinstance(payload.get("raw_meta"), dict) else None,
            "cache_state": "fresh",
            "last_synced_at": now,
            "deleted_at": None,
            "created_at": now,
            "updated_at": now,
        }
        pages.append(page)
    else:
        page["elementor_data_json"] = elementor_data
        if isinstance(slug, str) and 1 <= len(slug) <= 200:
            page["slug"] = slug
        page["raw_meta"] = payload.get("raw_meta") if isinstance(payload.get("raw_meta"), dict) else page.get("raw_meta")
        page["cache_state"] = "fresh" if page.get("cache_state") in ("unknown", "stale", "fresh") else "fresh"
        page["last_synced_at"] = now
        page["updated_at"] = now

    # link operation to internal page_id
    op["page_id"] = page.get("id")
    if isinstance(slug, str):
        op["slug"] = slug

    # ---- mark file consumed (ready -> consumed transition) ----
    pf["status"] = "consumed"
    pf["updated_at"] = now

    _set_op_status("succeeded", success=True, response_payload={"updated_wp_page_id": wp_page_id, "page_id": page.get("id"), "file_consumed": True})
    op["duration_ms"] = int((time.time() - t0) * 1000)

    # ---- persist all changes ----
    _save("wp_pages.json", _wrap(pages, pages_raw))
    _save("page_files.json", _wrap(pfiles, files_raw))
    _save("api_keys.json", _wrap(api_keys, keys_raw))
    _save("page_operations.json", _wrap(ops, ops_raw))

    return {
        "success": True,
        "site_id": site_id,
        "wp_page_id": wp_page_id,
        "page_id": page.get("id"),
        "operation_id": op_id,
        "file_id": file_id,
        "file_status": pf.get("status"),
    }

def delete_page(site_id, wp_page_id, force=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0057000" if __import__("os").path.isdir("./environment_mix/0057000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _b32_id(prefix):
        raw = os.urandom(12)
        s = base64.b32encode(raw).decode("ascii").rstrip("=")
        s = s.replace("O", "8").replace("I", "9").replace("L", "7")
        return f"{prefix}{s}"

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _truncate_payload(obj, max_str=2000, max_list=50, max_depth=3):
        def _t(o, d):
            if d <= 0:
                return "[truncated]"
            if o is None or isinstance(o, (bool, int, float)):
                return o
            if isinstance(o, str):
                return o if len(o) <= max_str else o[:max_str] + "…"
            if isinstance(o, list):
                out = []
                for it in o[:max_list]:
                    out.append(_t(it, d - 1))
                if len(o) > max_list:
                    out.append(f"[+{len(o)-max_list} more]")
                return out
            if isinstance(o, dict):
                out = {}
                for k in list(o.keys())[:200]:
                    out[str(k)] = _t(o[k], d - 1)
                if len(o) > 200:
                    out["__truncated_keys__"] = len(o) - 200
                return out
            return str(o)
        return _t(obj, max_depth)

    def _op_row(site_id_val, wp_page_id_val):
        ts = _now()
        return {
            "id": _b32_id("elm_op_"),
            "site_id": site_id_val,
            "tool_name": "delete_page",
            "page_id": None,
            "wp_page_id": wp_page_id_val,
            "slug": None,
            "input_file_id": None,
            "output_file_id": None,
            "request_payload": _truncate_payload({"site_id": site_id_val, "wp_page_id": wp_page_id_val, "force": force}),
            "response_payload": None,
            "http_status": None,
            "success": None,
            "status": "queued",
            "error_message": None,
            "duration_ms": None,
            "created_at": ts,
            "updated_at": ts,
        }

    def _op_transition(op, to_status):
        transitions = {
            "queued": ["running", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
        }
        cur = op.get("status")
        if cur not in transitions or to_status not in transitions[cur]:
            return False
        op["status"] = to_status
        op["updated_at"] = _now()
        return True

    def _resolve_key_for_site(site_row, api_keys):
        for k in api_keys:
            if k.get("status") != "active":
                continue
            allowed = k.get("allowed_site_ids")
            if allowed is not None and site_row.get("id") not in allowed:
                continue
            return k
        return None

    def _check_rate_quota(api_key_row, ops_rows, now_dt):
        rpm = api_key_row.get("rate_limit_per_minute")
        dq = api_key_row.get("daily_quota_ops")
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day)
        per_min = 0
        per_day = 0
        for op in ops_rows:
            ts = _parse_ts(op.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_start:
                per_day += 1
        if isinstance(rpm, int) and per_min >= rpm:
            return False, "RATE_LIMIT", f"Rate limit exceeded: {per_min}/{rpm} ops in the last minute."
        if isinstance(dq, int) and per_day >= dq:
            return False, "QUOTA_EXCEEDED", f"Daily quota exceeded: {per_day}/{dq} ops today."
        return True, None, None

    t0 = time.time()

    if not isinstance(site_id, str) or not re.match(r"^elm_site_[0-9A-HJKMNP-TV-Z]{17,}$", site_id):
        return _err("VALIDATION_ERROR", "Invalid site_id.")
    if not isinstance(wp_page_id, int) or wp_page_id < 1:
        return _err("VALIDATION_ERROR", "Invalid wp_page_id; must be an integer >= 1.")
    if force is not None and not isinstance(force, bool):
        return _err("VALIDATION_ERROR", "Invalid force; must be boolean.")

    sites = _load("wp_sites.json")
    pages = _load("wp_pages.json")
    ops = _load("page_operations.json")
    keys = _load("api_keys.json")

    site = next((s for s in sites if s.get("id") == site_id), None)
    op = _op_row(site_id, wp_page_id)
    ops.append(op)
    _save("page_operations.json", ops)

    if site is None:
        op["status"] = "failed"
        op["error_message"] = "Site not found."
        op["duration_ms"] = int((time.time() - t0) * 1000)
        op["updated_at"] = _now()
        _save("page_operations.json", ops)
        return _err("NOT_FOUND", "Site not found.")

    if site.get("status") != "active":
        op["status"] = "failed"
        op["error_message"] = "Site is disabled."
        op["duration_ms"] = int((time.time() - t0) * 1000)
        op["updated_at"] = _now()
        _save("page_operations.json", ops)
        return _err("CONFLICT", "Site is disabled.")

    key = _resolve_key_for_site(site, keys)
    if not key:
        op["status"] = "failed"
        op["error_message"] = "No active API key is authorized for this site."
        op["duration_ms"] = int((time.time() - t0) * 1000)
        op["updated_at"] = _now()
        _save("page_operations.json", ops)
        return _err("UNAUTHORIZED", "Not authorized for this site.")

    ok, code, msg = _check_rate_quota(key, ops, datetime.datetime.utcnow())
    if not ok:
        op["status"] = "failed"
        op["error_message"] = msg
        op["duration_ms"] = int((time.time() - t0) * 1000)
        op["updated_at"] = _now()
        _save("page_operations.json", ops)
        return _err(code, msg)

    for k in keys:
        if k.get("id") == key.get("id"):
            k["last_used_at"] = _now()
            k["updated_at"] = _now()
            break
    _save("api_keys.json", keys)

    # Find page cache row
    prow = next((p for p in pages if p.get("site_id") == site_id and p.get("wp_page_id") == wp_page_id), None)
    if prow is None:
        op["status"] = "failed"
        op["error_message"] = "Page not found."
        op["duration_ms"] = int((time.time() - t0) * 1000)
        op["updated_at"] = _now()
        _save("page_operations.json", ops)
        return _err("NOT_FOUND", "Page not found.")

    if not _op_transition(op, "running"):
        op["status"] = "failed"
        op["error_message"] = "Invalid operation transition."
        op["duration_ms"] = int((time.time() - t0) * 1000)
        op["updated_at"] = _now()
        _save("page_operations.json", ops)
        return _err("INVALID_TRANSITION", "Operation could not start.")

    # Offline: treat delete as successful remote action
    ts = _now()
    op["page_id"] = prow.get("id")
    op["slug"] = prow.get("slug")

    if force is True:
        # permanent: keep cached row but mark deleted
        prow["deleted_at"] = ts
        prow["wp_status"] = "trash"
        prow["cache_state"] = "unknown"
        prow["updated_at"] = ts
        op["http_status"] = 200
        op["success"] = True
        op["response_payload"] = _truncate_payload({"deleted": True, "force": True})
        _save("wp_pages.json", pages)
        _op_transition(op, "succeeded")
    else:
        # move to trash
        prow["deleted_at"] = ts
        prow["wp_status"] = "trash"
        prow["cache_state"] = "unknown"
        prow["updated_at"] = ts
        op["http_status"] = 200
        op["success"] = True
        op["response_payload"] = _truncate_payload({"trashed": True, "force": False})
        _save("wp_pages.json", pages)
        _op_transition(op, "succeeded")

    op["duration_ms"] = int((time.time() - t0) * 1000)
    _save("page_operations.json", ops)
    return {"site_id": site_id, "wp_page_id": wp_page_id, "success": True, "force": bool(force)}

