                if len(o) > max_list:
                    out.append(f"[+{len(o)-max_list} more]")
                return out
            if isinstance(o, dict):
                out = {}
                for k in list(o.keys())[:200]:
                    out[str(k)] = _t(o[k], d - 1)
                if len(o) > 200:
                    out["__truncated_keys__"] = len(o) - 200
                return out
            return str(o)
        return _t(obj, max_depth)

    def _op_row(site_id_val, slug_val):
        ts = _now()
        return {
            "id": _b32_id("elm_op_"),
            "site_id": site_id_val,
            "tool_name": "get_page_id_by_slug",
            "page_id": None,
            "wp_page_id": None,
            "slug": slug_val,
            "input_file_id": None,
            "output_file_id": None,
            "request_payload": _truncate_payload({"site_id": site_id_val, "slug": slug_val}),
            "response_payload": None,
            "http_status": None,
            "success": None,
            "status": "queued",
            "error_message": None,
            "duration_ms": None,
            "created_at": ts,
            "updated_at": ts,
        }

    def _op_transition(op, to_status):
        transitions = {
            "queued": ["running", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
        }
        cur = op.get("status")
        if cur not in transitions or to_status not in transitions[cur]:
            return False
        op["status"] = to_status
        op["updated_at"] = _now()
        return True

    def _resolve_key_for_site(site_row, api_keys):
        for k in api_keys:
            if k.get("status") != "active":
                continue
            allowed = k.get("allowed_site_ids")
            if allowed is not None and site_row.get("id") not in allowed:
                continue
            return k
        return None

    def _check_rate_quota(api_key_row, ops_rows, now_dt):
        rpm = api_key_row.get("rate_limit_per_minute")
        dq = api_key_row.get("daily_quota_ops")
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day)
        per_min = 0
        per_day = 0
        for op in ops_rows:
            ts = _parse_ts(op.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_start:
                per_day += 1
        if isinstance(rpm, int) and per_min >= rpm:
            return False, "RATE_LIMIT", f"Rate limit exceeded: {per_min}/{rpm} ops in the last minute."
        if isinstance(dq, int) and per_day >= dq:
            return False, "QUOTA_EXCEEDED", f"Daily quota exceeded: {per_day}/{dq} ops today."
        return True, None, None

    t0 = time.time()

    if not isinstance(site_id, str) or not re.match(r"^elm_site_[0-9A-HJKMNP-TV-Z]{17,}$", site_id):
        return _err("VALIDATION_ERROR", "Invalid site_id.")
    if not isinstance(slug, str) or not (1 <= len(slug) <= 200):
        return _err("VALIDATION_ERROR", "Invalid slug; must be a non-empty string of length 1..200.")

    sites = _load("wp_sites.json")
    pages = _load("wp_pages.json")
    ops = _load("page_operations.json")
    keys = _load("api_keys.json")

    site = next((s for s in sites if s.get("id") == site_id), None)
    op = _op_row(site_id, slug)
    ops.append(op)
    _save("page_operations.json", ops)

    if site is None:
        op["status"] = "failed"
        op["error_message"] = "Site not found."
        op["duration_ms"] = int((time.time() - t0) * 1000)
        op["updated_at"] = _now()
        _save("page_operations.json", ops)
        return _err("NOT_FOUND", "Site not found.")

    if site.get("status") != "active":
        op["status"] = "failed"
        op["error_message"] = "Site is disabled."
        op["duration_ms"] = int((time.time() - t0) * 1000)
        op["updated_at"] = _now()
        _save("page_operations.json", ops)
        return _err("CONFLICT", "Site is disabled.")

    key = _resolve_key_for_site(site, keys)
    if not key:
        op["status"] = "failed"
        op["error_message"] = "No active API key is authorized for this site."
        op["duration_ms"] = int((time.time() - t0) * 1000)
        op["updated_at"] = _now()
        _save("page_operations.json", ops)
        return _err("UNAUTHORIZED", "Not authorized for this site.")

    ok, code, msg = _check_rate_quota(key, ops, datetime.datetime.utcnow())
    if not ok:
        op["status"] = "failed"
        op["error_message"] = msg
        op["duration_ms"] = int((time.time() - t0) * 1000)
        op["updated_at"] = _now()
        _save("page_operations.json", ops)
        return _err(code, msg)

    for k in keys:
        if k.get("id") == key.get("id"):
            k["last_used_at"] = _now()
            k["updated_at"] = _now()
            break
    _save("api_keys.json", keys)

    if not _op_transition(op, "running"):
        op["status"] = "failed"
        op["error_message"] = "Invalid operation transition."
        op["duration_ms"] = int((time.time() - t0) * 1000)
        op["updated_at"] = _now()
        _save("page_operations.json", ops)
        return _err("INVALID_TRANSITION", "Operation could not start.")

    # Offline "query WP": use cache lookup; NOT_FOUND if none exists.
    match = next((p for p in pages if p.get("site_id") == site_id and p.get("deleted_at") is None and p.get("slug") == slug), None)
    if match is None:
        op["http_status"] = 404
        op["status"] = "failed"
        op["error_message"] = "No page found with that slug."
        op["duration_ms"] = int((time.time() - t0) * 1000)
        op["updated_at"] = _now()
        _save("page_operations.json", ops)
        return _err("NOT_FOUND", "No page found with that slug.", slug=slug)

    # Upsert semantics: ensure cache_state fresh and last_synced_at.
    ts = _now()
    match["cache_state"] = "fresh"
    match["last_synced_at"] = ts
    match["updated_at"] = ts
    _save("wp_pages.json", pages)

    op["wp_page_id"] = match.get("wp_page_id")
    op["page_id"] = match.get("id")
    op["http_status"] = 200
    op["response_payload"] = _truncate_payload({"wp_page_id": match.get("wp_page_id"), "page_id": match.get("id")})
    _op_transition(op, "succeeded")
    op["duration_ms"] = int((time.time() - t0) * 1000)
    _save("page_operations.json", ops)

    return {"site_id": site_id, "slug": slug, "wp_page_id": match.get("wp_page_id"), "page_id": match.get("id")}

def list_pages(site_id=None, query=None, slug=None, wp_page_id=None, wp_status=None, cache_state=None, include_deleted=None, limit=None, cursor=None, order_by=None, order_dir=None, **_extra):
    import json, os, datetime, re, base64, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0057000" if __import__("os").path.isdir("./environment_mix/0057000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _b32_id(prefix):
        raw = os.urandom(12)
        s = base64.b32encode(raw).decode("ascii").rstrip("=")
        s = s.replace("O", "8").replace("I", "9").replace("L", "7")
        return f"{prefix}{s}"

    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"): return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    t0 = time.time()

    # Resolve default site_id if omitted: choose an active site if possible.
    sites = _load("wp_sites.json")
    if site_id is None:
        active_sites = [s for s in sites if s.get("status") == "active"]
        site = active_sites[0] if active_sites else (sites[0] if sites else None)
        if not site:
            return _err("NOT_FOUND", "No sites configured.")
        site_id = site.get("id")
    else:
        if not isinstance(site_id, str) or not re.match(r"^elm_site_[0-9A-HJKMNP-TV-Z]{17,}$", site_id):
            return _err("VALIDATION_ERROR", "Invalid site_id; must match ^elm_site_[0-9A-HJKMNP-TV-Z]{17,}$.")

    site = next((s for s in sites if s.get("id") == site_id), None)
    if not site:
        return _err("NOT_FOUND", "Site not found.", site_id=site_id)

    if site.get("status") != "active":
        return _err("UNAUTHORIZED", "Site is disabled.", site_id=site_id)

    # Validate filters
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "Invalid query; must be string.")
    if slug is not None and not isinstance(slug, str):
        return _err("VALIDATION_ERROR", "Invalid slug; must be string.")
    if wp_page_id is not None:
        if not isinstance(wp_page_id, int) or wp_page_id < 1:
            return _err("VALIDATION_ERROR", "Invalid wp_page_id; must be integer >= 1.")
    if wp_status is not None and wp_status not in ["publish", "draft", "pending", "private", "future", "trash", "inherit", "unknown"]:
        return _err("VALIDATION_ERROR", "Invalid wp_status enum.")
    if cache_state is not None and cache_state not in ["fresh", "stale", "unknown"]:
        return _err("VALIDATION_ERROR", "Invalid cache_state enum.")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        return _err("VALIDATION_ERROR", "Invalid include_deleted; must be boolean.")
    # Relax limit validation to accept larger values (cap server-side) to match observed calls.
    if limit is not None:
        if not isinstance(limit, int) or limit < 1:
            return _err("VALIDATION_ERROR", "Invalid limit; must be integer >= 1.")
        limit_eff = min(limit, 2000)
    else:
        limit_eff = 200

    if order_by is not None and order_by not in ["updated_at", "created_at", "last_synced_at", "wp_page_id", "slug"]:
        return _err("VALIDATION_ERROR", "Invalid order_by enum.")
    if order_dir is not None and order_dir not in ["asc", "desc"]:
        return _err("VALIDATION_ERROR", "Invalid order_dir enum.")
    order_by = order_by or "updated_at"
    order_dir = order_dir or "desc"

    # Ambient auth + quota enforcement via any active API key allowed for site.
    keys = _load("api_keys.json")
    def _key_allows(k, sid):
        if not isinstance(k, dict): 
            return False
        if k.get("status") != "active":
            return False
        allow = k.get("allowed_site_ids")
        if allow is None:
            return True
        if isinstance(allow, list):
            return sid in allow
        return False
    active_key = next((_k for _k in keys if _key_allows(_k, site_id)), None)
    ops = _load("page_operations.json")

    # Create operation log row for this tool. page_operations.tool_name enum lacks list_pages; use get_page for audit bucket.
    op = {
        "id": _b32_id("elm_op_"),
        "site_id": site_id,
        "tool_name": "get_page",
        "page_id": None,
        "wp_page_id": wp_page_id,
        "slug": slug,
        "input_file_id": None,
        "output_file_id": None,
        "request_payload": {
            "site_id": site_id,
            "query": query,
            "slug": slug,
            "wp_page_id": wp_page_id,
            "wp_status": wp_status,
            "cache_state": cache_state,
            "include_deleted": include_deleted,
            "limit": limit,
            "cursor": cursor,
            "order_by": order_by,
            "order_dir": order_dir,
        },
        "response_payload": None,
        "http_status": None,
        "success": None,
        "status": "queued",
        "error_message": None,
        "duration_ms": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    ops.append(op)

    def _op_set(to_status, **updates):
        transitions = {
            "queued": ["running", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
        }
        cur = op.get("status")
        if cur not in transitions or to_status not in transitions[cur]:
            # keep conservative: if cannot transition, mark failed
            op["status"] = "failed"
        else:
            op["status"] = to_status
        op["updated_at"] = _now()
        for k, v in updates.items():
            op[k] = v

    # If no working key context, still allow read? Business rules mention UNAUTHORIZED when cannot access site.
    if not active_key:
        _op_set("failed", error_message="No active API key context is authorized for this site.", duration_ms=int((time.time() - t0) * 1000))
        _save("page_operations.json", ops)
        return _err("UNAUTHORIZED", "No active API key context is authorized for this site.", site_id=site_id)

    # Quota enforcement using ops log (best possible without api_key_id on ops)
    now = datetime.datetime.utcnow()
    one_min_ago = now - datetime.timedelta(minutes=1)
    day_ago = now - datetime.timedelta(days=1)
    rate_limit = active_key.get("rate_limit_per_minute")
    daily_quota = active_key.get("daily_quota_ops")

    recent = 0
    daily = 0
    for r in ops:
        ts = _parse_dt(r.get("created_at"))
        if not ts:
            continue
        if ts >= one_min_ago:
            recent += 1
        if ts >= day_ago:
            daily += 1

    if isinstance(rate_limit, int) and rate_limit >= 1 and recent > rate_limit:
        _op_set("failed", error_message="Quota exceeded (rate_limit_per_minute).", duration_ms=int((time.time() - t0) * 1000))
        _save("page_operations.json", ops)
        return _err("RATE_LIMIT", "Quota exceeded (rate_limit_per_minute).")
    if isinstance(daily_quota, int) and daily_quota >= 1 and daily > daily_quota:
        _op_set("failed", error_message="Quota exceeded (daily_quota_ops).", duration_ms=int((time.time() - t0) * 1000))
        _save("page_operations.json", ops)
        return _err("QUOTA_EXCEEDED", "Quota exceeded (daily_quota_ops).")

    active_key["last_used_at"] = _now()
    active_key["updated_at"] = _now()
    _save("api_keys.json", keys)

    _op_set("running")

    pages = _load("wp_pages.json")
    rows = [p for p in pages if p.get("site_id") == site_id]

    if not include_deleted:
        rows = [p for p in rows if p.get("deleted_at") is None]

    if slug is not None:
        rows = [p for p in rows if p.get("slug") == slug]
    if wp_page_id is not None:
        rows = [p for p in rows if p.get("wp_page_id") == wp_page_id]
    if wp_status is not None:
        rows = [p for p in rows if p.get("wp_status") == wp_status]
    if cache_state is not None:
        rows = [p for p in rows if p.get("cache_state") == cache_state]
    if query is not None and query.strip():
        q = query.strip().lower()
        def _hay(p):
            return f"{(p.get('title') or '')} {(p.get('slug') or '')}".lower()
        rows = [p for p in rows if q in _hay(p)]

    # Sorting
    def _sort_key(p):
        if order_by in ("updated_at", "created_at", "last_synced_at"):
            dt = _parse_dt(p.get(order_by))
            return dt or datetime.datetime.fromtimestamp(0)
        return p.get(order_by)

    reverse = (order_dir == "desc")
    try:
        rows.sort(key=_sort_key, reverse=reverse)
    except Exception:
        # Stable fallback
        rows.sort(key=lambda p: str(p.get(order_by)), reverse=reverse)

    total = len(rows)

    # Cursor is opaque; treat as "start after id" if matches any row id; else start at 0.
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _op_set("failed", error_message="Invalid cursor; must be string.", duration_ms=int((time.time() - t0) * 1000))
            _save("page_operations.json", ops)
            return _err("VALIDATION_ERROR", "Invalid cursor; must be string.")
        idx = next((i for i, r in enumerate(rows) if r.get("id") == cursor), None)
        if idx is not None:
            start = idx + 1

    page_rows = rows[start:start + limit_eff]
    has_more = (start + limit_eff) < total
    next_cursor = page_rows[-1].get("id") if (has_more and page_rows) else None

    _op_set(
        "succeeded",
        response_payload={"returned": len(page_rows), "total": total, "has_more": has_more},
        duration_ms=int((time.time() - t0) * 1000),
    )
    _save("page_operations.json", ops)

    return {
        "site_id": site_id,
        "data": page_rows,
        "meta": {
            "total": total,
            "limit": limit_eff,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "order_by": order_by,
            "order_dir": order_dir,
        },
    }

def list_operations(site_id=None, page_id=None, wp_page_id=None, tool_name=None, status=None, success=None, since=None, until=None, limit=None, cursor=None, order_dir=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0057000" if __import__("os").path.isdir("./environment_mix/0057000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # Accept RFC3339 with Z
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b64url_decode(s):
        try:
            if not isinstance(s, str):
                return None
            pad = '=' * ((4 - (len(s) % 4)) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("utf-8"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _b64url_encode(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _gen_id(prefix, rows):
        # ULID-like (not full ULID): time(ms) + random; base32 crockford
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import random
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        n = (ms << 80) | r
        s = ""
        for _ in range(26):
            s = alphabet[n & 31] + s
            n >>= 5
        cand = f"{prefix}_{s}"
        existing = {x.get("id") for x in rows if isinstance(x, dict)}
        while cand in existing:
            r = random.getrandbits(80)
            n = (ms << 80) | r
            s = ""
            for _ in range(26):
                s = alphabet[n & 31] + s
                n >>= 5
            cand = f"{prefix}_{s}"
        return cand

    # ---------- Load store ----------
    wp_sites = _load("wp_sites.json")
    wp_pages = _load("wp_pages.json")
    page_ops = _load("page_operations.json")
    api_keys = _load("api_keys.json")

    # ---------- Choose an ambient API key context (must be usable) ----------
    def _choose_key_for_site(target_site_id):
        # Prefer a key that allows the site (or all)
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            allowed = k.get("allowed_site_ids")
            if allowed is None:
                return k
            if isinstance(allowed, list) and target_site_id in allowed:
                return k
        return None

    # ---------- Determine default site ----------
    def _default_site_id():
        # Prefer an active site; else any site.
        for s in wp_sites:
            if isinstance(s, dict) and s.get("status") == "active":
                return s.get("id")
        for s in wp_sites:
            if isinstance(s, dict):
                return s.get("id")
        return None

    # ---------- Validate inputs ----------
    site_pat = re.compile(r"^elm_site_[0-9A-HJKMNP-TV-Z]{17,}$")
    page_pat = re.compile(r"^elm_page_[0-9A-HJKMNP-TV-Z]{17,}$")

    if site_id is not None and (not isinstance(site_id, str) or not site_pat.match(site_id)):
        return _err("VALIDATION_ERROR", "Invalid site_id.")
    if page_id is not None and (not isinstance(page_id, str) or not page_pat.match(page_id)):
        return _err("VALIDATION_ERROR", "Invalid page_id.")
    if wp_page_id is not None:
        if not isinstance(wp_page_id, int) or wp_page_id < 1:
            return _err("VALIDATION_ERROR", "Invalid wp_page_id; must be an integer >= 1.")
    tool_enum = {"create_page","get_page_id_by_slug","get_page","download_page_to_file","update_page","update_page_from_file","delete_page"}
    if tool_name is not None and (not isinstance(tool_name, str) or tool_name not in tool_enum):
        return _err("VALIDATION_ERROR", "Invalid tool_name.")
    status_enum = {"queued","running","succeeded","failed"}
    if status is not None and (not isinstance(status, str) or status not in status_enum):
        return _err("VALIDATION_ERROR", "Invalid status.")
    if success is not None and not isinstance(success, bool):
        return _err("VALIDATION_ERROR", "Invalid success; must be boolean.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.")
    if order_dir is None:
        order_dir = "desc"
    if not isinstance(order_dir, str) or order_dir not in {"asc", "desc"}:
        return _err("VALIDATION_ERROR", "Invalid order_dir; must be 'asc' or 'desc'.")
    since_dt = _parse_dt(since)
    if since is not None and since_dt is None:
        return _err("VALIDATION_ERROR", "Invalid since; must be RFC3339 date-time.")
    until_dt = _parse_dt(until)
    if until is not None and until_dt is None:
        return _err("VALIDATION_ERROR", "Invalid until; must be RFC3339 date-time.")
    if since_dt and until_dt and since_dt > until_dt:
        return _err("VALIDATION_ERROR", "Invalid time range: since must be <= until.")

    if site_id is None:
        site_id = _default_site_id()
        if site_id is None:
            return _err("NOT_FOUND", "No sites are configured.")

    # Check site exists
    site_row = next((s for s in wp_sites if isinstance(s, dict) and s.get("id") == site_id), None)
    if not site_row:
        return _err("NOT_FOUND", "Site not found.")

    # Authorization (ambient): must be able to access the site with some active key
    key_row = _choose_key_for_site(site_id)
    if not key_row:
        return _err("UNAUTHORIZED", "No active API key is authorized to access this site.")

    # ---------- Quota / rate limit enforcement (this call counts) ----------
    now = datetime.datetime.now(datetime.timezone.utc)
    minute_ago = now - datetime.timedelta(minutes=1)
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

    key_id = key_row.get("id")
    # Page operations is our request log; count for this key_id if present.
    def _op_key_matches(op):
        if not isinstance(op, dict):
            return False
        # Back-compat: if no api_key_id field exists historically, we cannot count it for rate limiting.
        return op.get("api_key_id") == key_id

    def _dt_from_row(v):
        if isinstance(v, str):
            d = _parse_dt(v)
            return d
        return None

    ops_for_key = [op for op in page_ops if _op_key_matches(op)]
    ops_last_min = 0
    ops_today = 0
    for op in ops_for_key:
        c = _dt_from_row(op.get("created_at"))
        if not c:
            continue
        if c >= minute_ago:
            ops_last_min += 1
        if c >= day_start:
            ops_today += 1

    rate_limit = key_row.get("rate_limit_per_minute")
    daily_quota = key_row.get("daily_quota_ops")
    if not isinstance(rate_limit, int) or rate_limit < 1:
        rate_limit = 60
    if not isinstance(daily_quota, int) or daily_quota < 1:
        daily_quota = 1000

    # Create operation row first (mandatory), then enforce quota against "would be exceeded"
    op_row = {
        "id": _gen_id("elm_op", page_ops),
        "site_id": site_id,
        "tool_name": "list_operations",
        "page_id": page_id,
        "wp_page_id": wp_page_id,
        "slug": None,
        "input_file_id": None,
        "output_file_id": None,
        "request_payload": {
            "filters": {
                "page_id": page_id,
                "wp_page_id": wp_page_id,
                "tool_name": tool_name,
                "status": status,
                "success": success,
                "since": since,
                "until": until,
            },
            "pagination": {"limit": limit, "cursor": cursor, "order_dir": order_dir},
        },
        "response_payload": None,
        "http_status": None,
        "success": None,  # informational
        "status": "queued",
        "error_message": None,
        "duration_ms": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
        # Non-schema extension for quota/audit correlation
        "api_key_id": key_id,
    }
    page_ops.append(op_row)
    _save("page_operations.json", page_ops)

    def _finish(op_status, error_message=None, response_payload=None):
        op_row["status"] = op_status
        op_row["error_message"] = error_message
        op_row["response_payload"] = response_payload
        op_row["duration_ms"] = int((time.time() - t0) * 1000)
        op_row["updated_at"] = _now_iso()
        key_row["last_used_at"] = _now_iso()
        key_row["updated_at"] = _now_iso()
        _save("api_keys.json", api_keys)
        _save("page_operations.json", page_ops)

    # Enforce quota/rate after logging the attempt
    # Note: include this operation itself in the "would be exceeded" check.
    if ops_last_min + 1 > rate_limit:
        _finish("failed", "Rate limit exceeded (per-minute).")
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_per_minute=rate_limit)
    if ops_today + 1 > daily_quota:
        _finish("failed", "Daily quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", daily_quota_ops=daily_quota)

    # Transition queued -> running
    op_row["status"] = "running"
    op_row["updated_at"] = _now_iso()
    _save("page_operations.json", page_ops)

    # Validate cross-site page filter if page_id provided
    if page_id is not None:
        pg = next((p for p in wp_pages if isinstance(p, dict) and p.get("id") == page_id), None)
        if not pg:
            _finish("failed", "page_id not found.")
            return _err("NOT_FOUND", "Page not found.")
        if pg.get("site_id") != site_id:
            _finish("failed", "Cross-site page_id filter forbidden.")
            return _err("CONFLICT", "Cross-site linkage is forbidden.")

    # Cursor decode (created_at, id)
    after_created_at = None
    after_id = None
    if cursor is not None:
        cur = _b64url_decode(cursor)
        if not isinstance(cur, dict) or "created_at" not in cur or "id" not in cur:
            _finish("failed", "Invalid cursor.")
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        after_created_at = _parse_dt(cur.get("created_at"))
        after_id = cur.get("id")
        if after_created_at is None or not isinstance(after_id, str):
            _finish("failed", "Invalid cursor payload.")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # ---------- Filter ----------
    def _match(op):
        if not isinstance(op, dict):
            return False
        if op.get("site_id") != site_id:
            return False
        if page_id is not None and op.get("page_id") != page_id:
            return False
        if wp_page_id is not None and op.get("wp_page_id") != wp_page_id:
            return False
        if tool_name is not None and op.get("tool_name") != tool_name:
            return False
        if status is not None and op.get("status") != status:
            return False
        if success is not None and op.get("success") != success:
            return False
        cdt = _parse_dt(op.get("created_at")) if isinstance(op.get("created_at"), str) else None
        if since_dt and cdt and cdt < since_dt:
            return False
        if until_dt and cdt and cdt > until_dt:
            return False
        if (since_dt or until_dt) and cdt is None:
            return False
        return True

    rows = [op for op in page_ops if _match(op)]

    # ---------- Sort ----------
    def _sort_key(op):
        cdt = _parse_dt(op.get("created_at")) if isinstance(op.get("created_at"), str) else None
        # treat missing as epoch
        if cdt is None:
            cdt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (cdt, op.get("id") or "")

    reverse = (order_dir == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    # ---------- Apply cursor pagination ----------
    if after_created_at is not None and after_id is not None:
        def _after(op):
            k = _sort_key(op)
            curk = (after_created_at, after_id)
            # if desc, cursor means "start after this in sorted order"
            if reverse:
                return k < curk
            else:
                return k > curk
        rows = [op for op in rows if _after(op)]

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = last.get("created_at")
        next_cursor = _b64url_encode({"created_at": last_dt, "id": last.get("id")})

    resp = {
        "operations": page,
        "site_id": site_id,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "order_dir": order_dir,
    }
    _finish("succeeded", response_payload={"count": len(page), "total": total, "has_more": has_more})
    return resp

def set_site_status(site_id, status, reason=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0057000" if __import__("os").path.isdir("./environment_mix/0057000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix, rows):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import random
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        n = (ms << 80) | r
        s = ""
        for _ in range(26):
            s = alphabet[n & 31] + s
            n >>= 5
        cand = f"{prefix}_{s}"
        existing = {x.get("id") for x in rows if isinstance(x, dict)}
        while cand in existing:
            r = random.getrandbits(80)
            n = (ms << 80) | r
            s = ""
            for _ in range(26):
                s = alphabet[n & 31] + s
                n >>= 5
            cand = f"{prefix}_{s}"
        return cand

    wp_sites = _load("wp_sites.json")
    page_ops = _load("page_operations.json")
    api_keys = _load("api_keys.json")

    # Validate inputs
    site_pat = re.compile(r"^elm_site_[0-9A-HJKMNP-TV-Z]{17,}$")
    if not isinstance(site_id, str) or not site_pat.match(site_id):
        return _err("VALIDATION_ERROR", "Invalid site_id.")
    if not isinstance(status, str) or status not in {"active", "disabled"}:
        return _err("VALIDATION_ERROR", "Invalid status; must be 'active' or 'disabled'.")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "Invalid reason; must be string.")

    site_row = next((s for s in wp_sites if isinstance(s, dict) and s.get("id") == site_id), None)
    if not site_row:
        return _err("NOT_FOUND", "Site not found.")

    # Authorization (ambient): require an active key that can access this site
    def _choose_key_for_site(target_site_id):
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            allowed = k.get("allowed_site_ids")
            if allowed is None:
                return k
            if isinstance(allowed, list) and target_site_id in allowed:
                return k
        return None

    key_row = _choose_key_for_site(site_id)
    if not key_row:
        return _err("UNAUTHORIZED", "No active API key is authorized to manage this site.")

    # Quota / rate limit enforcement (counts this call) with mandatory operation row even on reject
    now = datetime.datetime.now(datetime.timezone.utc)
    minute_ago = now - datetime.timedelta(minutes=1)
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    key_id = key_row.get("id")
    def _op_key_matches(op):
        return isinstance(op, dict) and op.get("api_key_id") == key_id

    ops_for_key = [op for op in page_ops if _op_key_matches(op)]
    ops_last_min = 0
    ops_today = 0
    for op in ops_for_key:
        c = _parse_dt(op.get("created_at"))
        if not c:
            continue
        if c >= minute_ago:
            ops_last_min += 1
        if c >= day_start:
            ops_today += 1

    rate_limit = key_row.get("rate_limit_per_minute")
    daily_quota = key_row.get("daily_quota_ops")
    if not isinstance(rate_limit, int) or rate_limit < 1:
        rate_limit = 60
    if not isinstance(daily_quota, int) or daily_quota < 1:
        daily_quota = 1000

    op_row = {
        "id": _gen_id("elm_op", page_ops),
        "site_id": site_id,
        "tool_name": "set_site_status",
        "page_id": None,
        "wp_page_id": None,
        "slug": None,
        "input_file_id": None,
        "output_file_id": None,
        "request_payload": {"site_id": site_id, "status": status, "reason": reason},
        "response_payload": None,
        "http_status": None,
        "success": None,
        "status": "queued",
        "error_message": None,
        "duration_ms": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
        "api_key_id": key_id,
    }
    page_ops.append(op_row)
    _save("page_operations.json", page_ops)

    def _finish(op_status, error_message=None, response_payload=None):
        op_row["status"] = op_status
        op_row["error_message"] = error_message
        op_row["response_payload"] = response_payload
        op_row["duration_ms"] = int((time.time() - t0) * 1000)
        op_row["updated_at"] = _now_iso()
        key_row["last_used_at"] = _now_iso()
        key_row["updated_at"] = _now_iso()
        _save("api_keys.json", api_keys)
        _save("page_operations.json", page_ops)

    if ops_last_min + 1 > rate_limit:
        _finish("failed", "Rate limit exceeded (per-minute).")
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_per_minute=rate_limit)
    if ops_today + 1 > daily_quota:
        _finish("failed", "Daily quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", daily_quota_ops=daily_quota)

    # Transition queued -> running
    op_row["status"] = "running"
    op_row["updated_at"] = _now_iso()
    _save("page_operations.json", page_ops)

    current = site_row.get("status")
    if current not in {"active", "disabled"}:
        _finish("failed", "Invalid current site status.")
        return _err("CONFLICT", "Site is in an unknown status; cannot transition.")

    # Enforce lifecycle transitions: active <-> disabled only
    allowed = {"active": {"disabled"}, "disabled": {"active"}}
    if status == current:
        # idempotent: succeed with no change but still "effect" is none; in real systems this is allowed
        # We'll treat as succeeded but update updated_at and record reason.
        site_row["updated_at"] = _now_iso()
        # Keep a lightweight audit trail in a non-schema field
        hist = site_row.get("status_history")
        if not isinstance(hist, list):
            hist = []
        hist.append({"from": current, "to": status, "at": _now_iso(), "reason": reason, "idempotent": True})
        site_row["status_history"] = hist
        _save("wp_sites.json", wp_sites)
        _finish("succeeded", response_payload={"site_id": site_id, "status": status, "idempotent": True})
        return {"site": site_row}

    if status not in allowed.get(current, set()):
        _finish("failed", f"Invalid transition from {current} to {status}.")
        return _err("CONFLICT", "Requested status transition is not allowed.", from_status=current, to_status=status)

    site_row["status"] = status
    site_row["updated_at"] = _now_iso()
    hist = site_row.get("status_history")
    if not isinstance(hist, list):
        hist = []
    hist.append({"from": current, "to": status, "at": _now_iso(), "reason": reason})
    site_row["status_history"] = hist
    _save("wp_sites.json", wp_sites)

    _finish("succeeded", response_payload={"site_id": site_id, "from": current, "to": status})
    return {"site": site_row}

def whoami(include_quota=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0057000" if __import__("os").path.isdir("./environment_mix/0057000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if include_quota is None:
        include_quota = False
    if not isinstance(include_quota, bool):
        return _err("VALIDATION_ERROR", "include_quota must be boolean.")

    api_keys = _load("api_keys.json")
    page_ops = _load("page_operations.json")
    wp_sites = _load("wp_sites.json")

    # Ambient auth: pick an active key as the presented identity.
    # If multiple exist, choose the one most recently used; else newest.
    active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active:
        return _err("UNAUTHORIZED", "Missing/invalid API key or key is revoked.")

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_or_epoch(s):
        d = _parse_dt(s)
        return d if d else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    active.sort(key=lambda k: (_dt_or_epoch(k.get("last_used_at")), _dt_or_epoch(k.get("updated_at")), _dt_or_epoch(k.get("created_at"))), reverse=True)
    key_row = active[0]

    # This endpoint "does not mutate data": do not write last_used_at or operations log.
    # Provide identity + optional quota usage snapshot.
    allowed_site_ids = key_row.get("allowed_site_ids")
    if allowed_site_ids is not None and not isinstance(allowed_site_ids, list):
        allowed_site_ids = None

    # Effective accessible sites list (for convenience)
    if allowed_site_ids is None:
        accessible_sites = [s.get("id") for s in wp_sites if isinstance(s, dict) and s.get("id")]
    else:
        accessible_sites = [sid for sid in allowed_site_ids if any(isinstance(s, dict) and s.get("id") == sid for s in wp_sites)]

    resp = {
        "api_key": {
            "id": key_row.get("id"),
            "key_prefix": key_row.get("key_prefix"),
            "label": key_row.get("label"),
            "status": key_row.get("status"),
            "allowed_site_ids": allowed_site_ids,
            "rate_limit_per_minute": key_row.get("rate_limit_per_minute"),
            "daily_quota_ops": key_row.get("daily_quota_ops"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
            "last_used_at": key_row.get("last_used_at"),
        },
        "entitlements": {
            "accessible_site_ids": accessible_sites,
        },
    }

    if include_quota:
        now = datetime.datetime.now(datetime.timezone.utc)
        minute_ago = now - datetime.timedelta(minutes=1)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

        key_id = key_row.get("id")
        def _op_key_matches(op):
            return isinstance(op, dict) and op.get("api_key_id") == key_id

        ops_for_key = [op for op in page_ops if _op_key_matches(op)]
        ops_last_min = 0
        ops_today = 0
        for op in ops_for_key:
            c = _parse_dt(op.get("created_at"))
            if not c:
                continue
            if c >= minute_ago:
                ops_last_min += 1
            if c >= day_start:
                ops_today += 1

        rate_limit = key_row.get("rate_limit_per_minute")
        daily_quota = key_row.get("daily_quota_ops")
        if not isinstance(rate_limit, int) or rate_limit < 1:
            rate_limit = 60
        if not isinstance(daily_quota, int) or daily_quota < 1:
            daily_quota = 1000

        resp["quota"] = {
            "rate_limit_per_minute": rate_limit,
            "used_last_minute": ops_last_min,
            "remaining_this_minute": max(0, rate_limit - ops_last_min),
            "daily_quota_ops": daily_quota,
            "used_today": ops_today,
            "remaining_today": max(0, daily_quota - ops_today),
            "as_of": now.isoformat(),
            "computed_in_ms": int((time.time() - t0) * 1000),
        }

    return resp
